import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  interpolateColors,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type QRCodeDangerProps = Record<string, any>;

const FinderPattern = ({
  x,
  y,
  color,
}: {
  x: number;
  y: number;
  color: string;
}) => (
  <g transform={`translate(${x}, ${y})`}>
    <path d="M0,0 h7 v7 h-7 Z" fill={color} />
    <path d="M1,1 h5 v5 h-5 Z" fill="white" />
    <path d="M2,2 h3 v3 h-3 Z" fill={color} />
  </g>
);

const QRCodeDanger: React.FC<QRCodeDangerProps> = ({
  backgroundColor = "#f0f4f8",
  transparentBackground = false,
  durationInSeconds = 8,
  initialColor = "#8cc63f",
  dangerColor = "#ef4444",
}) => {
  useFontLoader(["Nunito"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Dimensions & Layout ---
  const s = Math.min(width, height);
  const containerSize = s * 0.45;
  const borderWidth = s * 0.015;
  const borderRadius = s * 0.03;
  const padding = s * 0.04;
  const innerSize = containerSize - borderWidth * 2 - padding * 2;

  // --- Timings (Responsive to duration) ---
  const totalFrames = durationInSeconds * fps;
  const fAppear = totalFrames * 0.05;
  const tScanStart = totalFrames * 0.2;
  const tScanEnd = totalFrames * 0.45;
  const tColorStart = totalFrames * 0.55;
  const tColorEnd = totalFrames * 0.65;

  // --- Animations ---
  const appearScale = spring({
    frame: frame - fAppear,
    fps,
    config: { damping: 14, stiffness: 120 },
  });

  const laserOpacity = interpolate(
    frame,
    [tScanStart, tScanStart + 10, tScanEnd - 10, tScanEnd],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const laserY = interpolate(
    frame,
    [tScanStart + 5, tScanEnd - 5],
    [0, innerSize + 20],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const scanFlash = interpolate(
    frame,
    [tScanEnd - 10, tScanEnd, tScanEnd + 15],
    [0, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const currentColor = interpolateColors(
    frame,
    [tColorStart, tColorEnd],
    [initialColor, dangerColor]
  );

  const dangerGlowOpacity = interpolate(
    frame,
    [tColorStart, tColorEnd],
    [0, 0.6],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const pulsePhase = Math.max(0, frame - tColorEnd);
  const pulseScale = 1 + Math.sin(pulsePhase * 0.2) * 0.02;

  const finalScale = appearScale * pulseScale;

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // --- QR Code Data Generation ---
  const modules = useMemo(() => {
    const mods = [];
    for (let y = 0; y < 21; y++) {
      for (let x = 0; x < 21; x++) {
        // Skip finder patterns + 1px white border
        if (x < 8 && y < 8) continue;
        if (x > 12 && y < 8) continue;
        if (x < 8 && y > 12) continue;

        // Timing patterns (V1)
        if (y === 6 && x >= 8 && x <= 12) {
          if (x % 2 === 0) mods.push({ x, y });
          continue;
        }
        if (x === 6 && y >= 8 && y <= 12) {
          if (y % 2 === 0) mods.push({ x, y });
          continue;
        }

        // Pseudo-random dense distribution for data
        const n = Math.sin(x * 12.9898 + y * 78.233) * 43758.5453;
        const rand = n - Math.floor(n);

        if (rand > 0.45) {
          mods.push({ x, y });
        }
      }
    }
    return mods;
  }, []);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "'Nunito', sans-serif",
      }}
    >
      <div
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          width: "100%",
          height: "100%",
        }}
      >
        <div
          style={{
            position: "relative",
            width: containerSize,
            height: containerSize,
            border: `${borderWidth}px solid ${currentColor}`,
            borderRadius: borderRadius,
            backgroundColor: "white",
            padding: padding,
            boxSizing: "border-box",
            transform: `scale(${finalScale})`,
            boxShadow: "0 20px 40px rgba(0,0,0,0.1)",
            transition: "none",
          }}
        >
          {/* Menacing Danger Glow behind the container */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              backgroundColor: dangerColor,
              filter: "blur(50px)",
              opacity: dangerGlowOpacity,
              zIndex: -2,
              borderRadius: borderRadius,
              transition: "none",
            }}
          />

          {/* QR Code Canvas */}
          <div
            style={{
              width: innerSize,
              height: innerSize,
              position: "relative",
              overflow: "hidden",
            }}
          >
            <svg
              width={innerSize}
              height={innerSize}
              viewBox="0 0 21 21"
              style={{ position: "absolute", top: 0, left: 0 }}
            >
              <FinderPattern x={0} y={0} color={currentColor} />
              <FinderPattern x={14} y={0} color={currentColor} />
              <FinderPattern x={0} y={14} color={currentColor} />
              {modules.map((m, i) => (
                <rect
                  key={i}
                  x={m.x}
                  y={m.y}
                  width={1}
                  height={1}
                  fill={currentColor}
                />
              ))}
            </svg>

            {/* Scanning Laser Beam */}
            <div
              style={{
                position: "absolute",
                top: laserY - 20,
                left: 0,
                width: "100%",
                height: 20,
                background:
                  "linear-gradient(to bottom, rgba(255, 50, 50, 0), rgba(255, 50, 50, 0.4))",
                borderBottom: "4px solid #ff3333",
                boxShadow: "0 5px 15px rgba(255, 50, 50, 0.6)",
                opacity: laserOpacity,
                zIndex: 10,
                transition: "none",
              }}
            />

            {/* Completion Flash */}
            <div
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                backgroundColor: "white",
                opacity: scanFlash,
                zIndex: 20,
                transition: "none",
              }}
            />
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default QRCodeDanger;